from PIL import Image; import numpy as np
im=np.array(Image.open('/var/exam/capture.png').convert('L')).astype(int)
# find dark round blobs (bores) 
ys,xs=np.where(im<60)
print(im.shape, len(xs))
from collections import defaultdict
# simple clustering
pts=list(zip(xs,ys)); cl=[]
for x,y in pts:
    for c in cl:
        if abs(c[0][0]-x)<10 and abs(c[0][1]-y)<10: c.append((x,y)); break
    else: cl.append([(x,y)])
for c in cl:
    a=np.array(c); 
    if len(c)>5: print(a.mean(0), len(c))
EOF

