args.command:
python3 - <<'EOF'
from PIL import Image
im=Image.open('/var/exam/capture.png').convert('L'); W,H=im.size; p=im.load()
g=Image.open('/opt/exam/grader/golden.png').convert('L'); q=g.load()
def blobs(px,thr):
    cl=[]
    for y in range(H):
        for x in range(W):
            if px[x,y]<thr:
                for c in cl:
                    if abs(c[-1][0]-x)<12 and abs(c[-1][1]-y)<12: c.append((x,y)); break
                else: cl.append([(x,y)])
    return [(sum(a for a,b in c)/len(c), sum(b for a,b in c)/len(c), len(c)) for c in cl if len(c)>4]
print("capture bores", blobs(p,70))
print("golden bores", blobs(q,100))
# fixture top-face mask: find rows/cols profile at mid
print([p[x,180] for x in range(140,330,5)])
print([p[235,y] for y in range(110,250,4)])
EOF

